const validCustomSymptoms=x=>Array.isArray(x)&&x.length<=20&&x.every((v,i)=>typeof v==="string"&&v.length>0&&v.length<=60&&v.trim()===v&&x.findIndex(y=>typeof y==="string"&&y.toLowerCase()===v.toLowerCase())===i);
const fresh=()=>({v:1,settings:{mode:"natural",age:"adult",unit:"C",weekStart:"mon",defaultCycle:null,defaultPeriod:5,onboarded:false,showIdeas:true,showRituals:true,showEstimates:true,showPhases:true,quietMotion:false,largeText:false,theme:"system",showGarden:true,customSymptoms:[]},logs:{},rituals:{},sample:false});
let data,personalData=null,demo=false,readError=false,writeError=false,tab="today",month=new Date(),selected=iso;
