function persist(){if(demo){alertMsg("Demo is read-only. Exit demo to edit your journal.");return false;}if(readError){alertMsg("Saved data could not be read. Restore a backup before editing.");return false;}try{localStorage.setItem(KEY,JSON.stringify(data));writeError=false;return true;}catch(e){writeError=true;alertMsg("Changes could not be saved. Check device storage.");return false;}}
function patch(day,updates){if(readError)return alertMsg("Storage needs recovery before editing.");const previous=data.logs[day]||{},next={...previous,...updates};for(const key of Object.keys(updates))if(updates[key]===undefined)delete next[key];for(const k in next)if(next[k]===null||next[k]===undefined||next[k]===""||(Array.isArray(next[k])&&!next[k].length))delete next[k];if(Object.keys(next).length)data.logs[day]=next;else delete data.logs[day];if(!persist()){if(Object.keys(previous).length)data.logs[day]=previous;else delete data.logs[day];return;}render();alertMsg("Entry saved on this device.");}
function card(title,body,cls=""){return '<section class="panel '+cls+'"><h2>'+title+'</h2>'+body+'</section>'}
