const RITUALS=[["walk","A comfortable walk"],["rest","A quiet break"],["meal","A satisfying meal"],["journal","A quick reflection"],["strength","Comfortable movement"]];
function ritualCard(){const entries=(data.rituals||{})[iso]||[];return card("Your little things",'<p class="fine">Optional reflections, not health rules. Nothing to keep up with.</p><div class="ritual-list">'+RITUALS.map(([id,name])=>{const found=entries.find(x=>x.id===id);return '<div class="ritual-row"><strong>'+name+'</strong><label class="field">Reflection <select data-ritual="'+id+'" aria-label="Reflection for '+name+'"><option value="">Not recorded</option>'+[["tried","Tried it"],["better","Felt better"],["same","About the same"],["not","Not helpful"]].map(([v,label])=>'<option value="'+v+'" '+(found?.result===v?"selected":"")+'>'+label+'</option>').join("")+'</select></label></div>'}).join("")+'</div><p class="fine">Your observations are personal and do not establish cause and effect.</p>')}
